const LOCALES = ['en', 'zh-CN', 'ja', 'ko', 'es', 'fr', 'de', 'pt', 'ru', 'ar'] as const;

const NATIVE_NAMES: Record<(typeof LOCALES)[number], string> = {
  en: 'English',
  'zh-CN': '中文',
  ja: '日本語',
  ko: '한국어',
  es: 'Español',
  fr: 'Français',
  de: 'Deutsch',
  pt: 'Português',
  ru: 'Русский',
  ar: 'العربية',
};

const BR_2_5_KEYS = [
  'demo.title',
  'demo.currentLocale',
  'nav.console',
  'nav.docs',
  'localeSwitch.label',
  'localeSwitch.options.en',
  'localeSwitch.options.zh-CN',
  'localeSwitch.options.ja',
  'localeSwitch.options.ko',
  'localeSwitch.options.es',
  'localeSwitch.options.fr',
  'localeSwitch.options.de',
  'localeSwitch.options.pt',
  'localeSwitch.options.ru',
  'localeSwitch.options.ar',
  'errors.notFound.title',
  'errors.notFound.description',
  'errors.notFound.backHome',
  'a11y.skipToContent',
] as const;

// flag emoji codepoint range: U+1F1E6..U+1F1FF (regional indicators)
const FLAG_EMOJI_RE = /[\u{1F1E6}-\u{1F1FF}]/u;

function read(path: string): string {
  return readFileSync(path, 'utf8');
}
function readJson(path: string): any {
  return JSON.parse(read(path));
}
function flatten(obj: any, prefix = ''): string[] {
  const out: string[] = [];
  for (const [k, v] of Object.entries(obj)) {
    const p = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === 'object' && !Array.isArray(v)) out.push(...flatten(v, p));
    else out.push(p);
  }
  return out;
}
function pluralBranches(msg: string): string[] {
  const start = msg.indexOf('plural');
  if (start < 0) return [];
  const after = msg.slice(start);
  const re = /(=\d+|zero|one|two|few|many|other)\s*\{/g;
  const out: string[] = [];
  let m: RegExpExecArray | null;
  while ((m = re.exec(after)) !== null) if (m[1]) out.push(m[1]);
  return out;
}

