  // helper that runs check-i18n-keys.ts against a fixture root
  function findTsxBin(): string | null {
    const candidates = [
      join(ROOT, 'node_modules/.bin/tsx'),
      join(ROOT, 'node_modules/.pnpm/node_modules/.bin/tsx'),
    ];
    for (const c of candidates) {
      if (existsSync(c)) return c;
    }
    return null;
  }
  function runCheck(fixtureRoot: string): { code: number; stderr: string; stdout: string } {
    const tsxBin = findTsxBin();
    if (!tsxBin) return { code: -1, stderr: 'tsx not installed', stdout: '' };
    const out = spawnSync(tsxBin, [join(SCRIPTS, 'check-i18n-keys.ts'), '--root', fixtureRoot], {
      cwd: ROOT,
      encoding: 'utf8',
      timeout: 30_000,
    });
    return { code: out.status ?? -1, stderr: out.stderr ?? '', stdout: out.stdout ?? '' };
  }

  function copyFixture(): string {
    const tmp = mkdtempSync(join(tmpdir(), 'i18n-check-'));
    const dest = join(tmp, 'apps/console/messages');
    mkdirSync(dest, { recursive: true });
    for (const l of LOCALES) {
      const src = readJson(join(MESSAGES, l, 'common.json'));
      mkdirSync(join(dest, l), { recursive: true });
      writeFileSync(join(dest, l, 'common.json'), JSON.stringify(src, null, 2), 'utf8');
    }
    return tmp;
  }

